-- Geografía electoral de Nuevo León (fuente: catálogos INE)

-- ============================================================
-- 03 - Seed: catalogo de geografia electoral de Nuevo Leon
-- ============================================================
-- Generado automaticamente a partir de los archivos fuente en
-- '/Users/javierramirez/Desktop/INPOL IA/':
--   - Cartografia/Tablas (Valores).xlsx
--       hojas: tbl_cat_entidad_federal, tbl_cat_municipios,
--       tbl_cat_distrito_local, tbl_rel_municipio_distritos,
--       tbl_distrito_seccion
--   - Cartografia/Catalogo de Municipios y Distritos.xls
--       (formato antiguo pero en realidad es un .xlsx con extension .xls;
--       se pudo leer copiando el archivo con extension .xlsx. Contenido
--       identico a tbl_rel_municipio_distritos, 57 relaciones: se usa solo
--       como validacion cruzada, no se vuelve a insertar)
--   - DBs INE/Gobernador2015NuevoLeonSeccion.csv
--   - DBs INE/DiputadosMR2015NuevoLeonSeccion.csv
--   - Ine Nuevo Leon/DiaD (Seccion Casilla).xlsx
--
-- No editar a mano: regenerar desde las fuentes si cambian.
-- Catalogo GLOBAL (sin tenant_id): geografia electoral es la misma para
-- todos los clientes de la plataforma.
--
-- DECISIONES Y HALLAZGOS IMPORTANTES (leer antes de modificar):
--
-- 1) Los conteos de filas mencionados en el encargo original cuentan la
--    fila de encabezado de cada hoja de Excel como si fuera un registro.
--    Los conteos reales de DATOS son:
--      tbl_cat_municipios          -> 51 municipios  (no 52)
--      tbl_cat_distrito_local      -> 12 distritos   (no 13)
--      tbl_rel_municipio_distritos -> 57 relaciones  (no 58)
--      tbl_distrito_seccion        -> 2602 relaciones (coincide: "~2602")
--    51 municipios es ademas el numero oficial de municipios de Nuevo Leon,
--    asi que se confirma que 51 (no 52) es el valor correcto.
--
-- 2) INCONSISTENCIA DE ESQUEMA DISTRITAL ENCONTRADA EN LAS FUENTES:
--    tbl_cat_distrito_local / tbl_rel_municipio_distritos / Catalogo de
--    Municipios y Distritos.xls usan una numeracion de 12 distritos
--    (clave 01-12), mientras que tbl_distrito_seccion y las DOS columnas
--    ID_DISTRITO de los CSV del INE (Gobernador y DiputadosMR 2015) usan
--    una numeracion de 26 distritos (clave 01-26), cruzada 1:1 y sin
--    conflicto contra tbl_distrito_seccion (0 discrepancias).
--    Se investigo cual es cual:
--      - Nuevo Leon tiene 26 distritos LOCALES de mayoria relativa desde
--        al menos 2015 hasta 2023 (Congreso del Estado: 26 MR + 16 RP).
--      - Nuevo Leon tiene 12 distritos FEDERALES segun la redistritacion
--        de 2017 (antes tenia menos). La composicion municipal de la
--        hoja tbl_cat_distrito_local / tbl_rel_municipio_distritos
--        coincide en estructura (agrupa municipios rurales del sur/norte
--        en distritos grandes) con la geografia FEDERAL, no con la local.
--    CONCLUSION: el nombre "distrito_local" en tbl_cat_distrito_local y
--    tbl_rel_municipio_distritos esta MAL ETIQUETADO en el archivo fuente.
--    En este seed:
--      - tbl_cat_distrito_local (12 filas)       -> distritos ambito='federal'
--      - ID_DISTRITO de los CSV INE / tbl_distrito_seccion (26 filas) -> distritos ambito='local'
--    Los nombres de los 12 distritos federales se dejan tal cual venian
--    ("DISTRITO 01".."DISTRITO 12"); no hay nombre oficial ni cabecera en
--    la fuente para ellos (la columna bt_distrito_local_cabecera es una
--    bandera booleana sin informacion util, no un nombre de cabecera).
--
-- 3) tbl_rel_municipio_distritos / Catalogo de Municipios y Distritos.xls
--    relacionan municipio <-> distrito FEDERAL solo a nivel MUNICIPIO (no
--    seccion), y varios municipios estan partidos entre mas de un distrito
--    federal (ej. SAN NICOLAS DE LOS GARZA aparece en distrito 03 y 04;
--    MONTERREY aparece en 05, 06, 07 y 10). Por lo tanto NO es posible
--    derivar de forma confiable un distrito_federal_id por SECCION a partir
--    de esos datos, y el esquema no incluye una tabla puente municipio<->
--    distrito. Por eso secciones.distrito_federal_id se deja NULL en todo
--    este seed (dato no disponible a nivel seccion en las fuentes
--    entregadas). secciones.distrito_local_id si se puede poblar de forma
--    confiable porque tbl_distrito_seccion y los CSV INE dan la relacion
--    exacta a nivel seccion y coinciden entre si al 100%.
--
-- 4) tbl_cat_tipo_apoyo (catalogo de "tipo de apoyo social") no tiene tabla
--    correspondiente en este esquema de geografia electoral: se reporta su
--    existencia pero no se carga aqui (pertenece a otro modulo del sistema).
--
-- 5) Convencion de claves: se usa el formato con ceros a la izquierda que
--    ya sugiere el DDL de referencia (ej. distrito '05', seccion '1432'):
--      estados.clave     -> 2 digitos  ('19')
--      municipios.clave  -> 3 digitos  ('001'..'051')
--      distritos.clave   -> 2 digitos  ('01'..'12' federal, '01'..'26' local)
--      secciones.clave   -> 4 digitos  ('0001'..'2709')
--    Los nombres de municipio se tomaron de tbl_cat_municipios (catalogo
--    oficial) y no de la columna MUNICIPIO de los CSV del INE, que tiene
--    pequenas variantes de captura (ej. 'EL CARMEN' vs 'CARMEN').
--
-- 6) secciones.tipo (urbana/rural/mixta) y secciones.latitud/longitud: NO
--    hay esa informacion en ninguna de las fuentes entregadas. Se dejan
--    NULL (ya anticipado por el TODO de PostGIS en el DDL de referencia).
--
-- 7) casillas se carga desde 'Ine Nuevo Leon/DiaD (Seccion Casilla).xlsx'
--    (hoja 'DiaD', columnas Movilizador/SECCION/CASILLA_COMPUESTA/VOTOS/
--    PROMOVIDOS/VOTANTES: datos operativos de movilizacion, no el catalogo
--    oficial de casillas del INE). De sus 6585 pares (seccion, casilla)
--    distintos, 44 filas (24 secciones) no existen en el catalogo oficial
--    de 2602 secciones (tbl_distrito_seccion / CSV INE) y se excluyen por
--    la FK a secciones. tipo de casilla se infiere del prefijo de la clave:
--    B->basica, C->contigua, E->especial; el prefijo 'S' (27 filas) no
--    corresponde a ninguna convencion oficial conocida del INE y se deja
--    con tipo NULL en vez de adivinar.
--
-- 8) ESTRATEGIA DE INSERCION MASIVA: para secciones (2602 filas) y para los
--    resultados (ver 04-seed-resultados-2015.sql, ~63000 filas) se usa
--    'insert ... select ... from unnest(arreglo1, arreglo2, ...)'
--    en vez de miles de 'insert into ... select ... where clave = X' o de
--    un 'values (...)' gigante con subconsultas repetidas por fila. Un
--    'insert...select' con joins contra unnest() hace UN solo join por
--    tabla catalogo (no uno por fila), por lo que Postgres lo planea como
--    un hash/merge join en vez de miles de index lookups anidados; es la
--    forma mas rapida de ejecutar y, al quedar todo en un solo statement,
--    tambien es mas corta de leer que miles de inserts individuales.
--    Todos los inserts son reejecutables via 'on conflict ... do nothing'.
-- ============================================================

create extension if not exists pgcrypto;






-- --- estados -------------------------------------------------------
insert into estados (clave, nombre, abreviatura) values
  ('19', 'NUEVO LEON', 'NL')
on conflict (clave) do nothing;

-- --- municipios (51 filas, clave zero-padded 3 digitos) ---
insert into municipios (estado_id, clave, nombre)
select e.id, v.clave, v.nombre
from estados e
join unnest(
array[
    '001','002','003','004','005','006','007','008','009','010','011','012','013','014','015','016','017','018','019','020','021','022','023','024','025','026','027','028','029','030','031','032','033','034','035','036','037','038','039','040','041','042','043','044','045','046','047','048','049','050','051'
