) as v(clave, nombre) on true
where e.clave = '19'
on conflict (estado_id, clave) do nothing;

-- --- distritos ambito='federal' (12 filas) ---
-- fuente: tbl_cat_distrito_local (ver nota 2 del encabezado sobre el
-- etiquetado incorrecto en el archivo origen)
insert into distritos (estado_id, clave, nombre, ambito, cabecera)
select e.id, v.clave, v.nombre, 'federal', NULL
from estados e
join unnest(
array[
    '01','02','03','04','05','06','07','08','09','10','11','12'
