) as v(clave, nombre) on true
where e.clave = '19'
on conflict (estado_id, ambito, clave) do nothing;

-- --- distritos ambito='local' (26 filas) ---
-- fuente: ID_DISTRITO + CABECERA_DISTRITAL de los CSV INE 2015, cruzado
