-- --- casillas (6541 filas) ---
-- fuente: 'Ine Nuevo Leon/DiaD (Seccion Casilla).xlsx' (hoja DiaD), columnas
-- SECCION + CASILLA_COMPUESTA. Se excluyeron las filas cuya seccion no
-- existe en el catalogo oficial de 2602 secciones (ver nota 7 del
-- encabezado). tipo se infiere del prefijo de la clave (B/C/E); prefijo
-- 'S' se deja con tipo NULL por no tener una convencion oficial conocida.
insert into casillas (seccion_id, clave, tipo)
select s.id, v.clave, v.tipo
from estados e
join secciones s on s.estado_id = e.id
join unnest(
